```python
class LRUCache:
    """Least Recently Used cache with O(1) get and put operations."""

    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("Capacity must be a positive integer")
        self.capacity = capacity
        self._cache: dict = {}  # key -> value, insertion-ordered (Python 3.7+)

    def get(self, key):
        """Return value for key, or None if not found. Marks key as recently used."""
        if key not in self._cache:
            return None
        # Move to end (most recently used)
        value = self._cache.pop(key)
        self._cache[key] = value
        return value

    def put(self, key, value) -> None:
        """Insert or update key-value pair. Evicts LRU item if at capacity."""
        if key in self._cache:
            # Remove old entry so re-insertion moves it to the end
            del self._cache[key]
        elif len(self._cache) >= self.capacity:
            # Evict least recently used (first item in ordered dict)
            oldest_key = next(iter(self._cache))
            del self._cache[oldest_key]
        self._cache[key] = value

    def delete(self, key) -> bool:
        """Remove key if present. Returns True if removed, False otherwise."""
        if key in self._cache:
            del self._cache[key]
            return True
        return False

    def clear(self) -> None:
        self._cache.clear()

    def __len__(self) -> int:
        return len(self._cache)

    def __contains__(self, key) -> bool:
        return key in self._cache

    def __repr__(self) -> str:
        return f"LRUCache(capacity={self.capacity}, size={len(self._cache)})"
```

How it works: relies on Python 3.7+ dict preserving insertion order. `get` pops and re-inserts to move the key to the end. `put` evicts the first key (oldest access) when at capacity.

Edge cases handled:
- Zero/negative capacity raises immediately
- `get` on missing key returns `None` (no KeyError)
- `put` with existing key updates value without growing size
- `delete` is safe on missing keys
- Works with any hashable key type, including `None`

If you need thread safety, wrap with `threading.Lock`. If you need TTL expiry or a decorator interface, say the word.

# Observer Pattern

The Observer pattern defines a one-to-many dependency between objects: when one object (the subject) changes state, all its dependents (observers) are notified automatically.

## When to use it

- Event systems, pub/sub messaging
- UI state management (React's state, MobX)
- Decoupling components that react to changes

## TypeScript Implementation

```typescript
// The contract for any observer
interface Observer<T> {
  update(data: T): void;
}

// The subject that holds state and notifies observers
class EventEmitter<T> {
  private observers: Set<Observer<T>> = new Set();

  subscribe(observer: Observer<T>): () => void {
    this.observers.add(observer);
    // Return an unsubscribe function
    return () => this.observers.delete(observer);
  }

  notify(data: T): void {
    for (const observer of this.observers) {
      observer.update(data);
    }
  }
}

// --- Practical example: price alert system ---

interface PriceUpdate {
  symbol: string;
  price: number;
  timestamp: Date;
}

// Concrete observer: logs to console
class PriceLogger implements Observer<PriceUpdate> {
  update(data: PriceUpdate): void {
    console.log(`[${data.timestamp.toISOString()}] ${data.symbol}: $${data.price}`);
  }
}

// Concrete observer: triggers alert when threshold crossed
class ThresholdAlert implements Observer<PriceUpdate> {
  constructor(
    private symbol: string,
    private threshold: number
  ) {}

  update(data: PriceUpdate): void {
    if (data.symbol === this.symbol && data.price > this.threshold) {
      console.log(`⚠️ ALERT: ${data.symbol} crossed $${this.threshold} — now at $${data.price}`);
    }
  }
}

// Usage
const priceFeed = new EventEmitter<PriceUpdate>();

const logger = new PriceLogger();
const btcAlert = new ThresholdAlert("BTC", 100_000);

const unsubLogger = priceFeed.subscribe(logger);
priceFeed.subscribe(btcAlert);

priceFeed.notify({ symbol: "BTC", price: 99_500, timestamp: new Date() });
// logs price, no alert

priceFeed.notify({ symbol: "BTC", price: 101_200, timestamp: new Date() });
// logs price + triggers alert

// Later: stop logging
unsubLogger();

priceFeed.notify({ symbol: "BTC", price: 102_000, timestamp: new Date() });
// only alert fires, no log
```

## Key design decisions here

1. **Generic `<T>`** — the emitter doesn't care what data flows through it. Type safety without coupling.
2. **`Set` over array** — prevents duplicate subscriptions, O(1) delete.
3. **Unsubscribe via returned function** — cleaner than forcing observers to keep a reference to the subject. Same pattern RxJS uses.
4. **Interface, not abstract class** — any object can be an observer without inheritance constraints.

## The tradeoff

Observer decouples sender from receiver, but debugging gets harder — you can't easily trace "who reacted to this event and in what order." In complex systems, consider adding event IDs or switching to a reactive library (RxJS) that gives you operators for filtering, throttling, and error handling out of the box.

```rust
use std::time::Duration;
use std::thread;

/// Retry a fallible operation with exponential backoff.
///
/// - `max_retries`: maximum number of attempts (0 means try once, no retries)
/// - `initial_delay`: base delay before first retry
/// - `max_delay`: cap on the backoff duration
/// - `op`: the operation to retry; receives the current attempt number (0-indexed)
///
/// Returns `Ok(T)` on first success, or the last `Err(E)` after all attempts are exhausted.
pub fn retry_with_backoff<T, E, F>(
    max_retries: u32,
    initial_delay: Duration,
    max_delay: Duration,
    mut op: F,
) -> Result<T, E>
where
    F: FnMut(u32) -> Result<T, E>,
{
    let total_attempts = max_retries.saturating_add(1); // avoid overflow if max_retries == u32::MAX
    let mut last_err: Option<E> = None;

    for attempt in 0..total_attempts {
        match op(attempt) {
            Ok(val) => return Ok(val),
            Err(e) => {
                last_err = Some(e);

                // Don't sleep after the final attempt
                if attempt < max_retries {
                    let exp = attempt.min(63); // prevent shift overflow (2^63 is already huge)
                    let backoff = initial_delay.saturating_mul(2u32.saturating_pow(exp));
                    let capped = backoff.min(max_delay);
                    thread::sleep(capped);
                }
            }
        }
    }

    // total_attempts >= 1, so last_err is always Some
    Err(last_err.unwrap())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::cell::Cell;
    use std::time::Instant;

    #[test]
    fn succeeds_immediately() {
        let result = retry_with_backoff(3, Duration::from_millis(10), Duration::from_secs(1), |_| {
            Ok::<_, &str>(42)
        });
        assert_eq!(result, Ok(42));
    }

    #[test]
    fn fails_then_succeeds() {
        let count = Cell::new(0);
        let result = retry_with_backoff(5, Duration::from_millis(1), Duration::from_secs(1), |_| {
            let c = count.get();
            count.set(c + 1);
            if c < 3 {
                Err("not yet")
            } else {
                Ok("done")
            }
        });
        assert_eq!(result, Ok("done"));
        assert_eq!(count.get(), 4);
    }

    #[test]
    fn exhausts_all_retries() {
        let count = Cell::new(0u32);
        let result = retry_with_backoff(2, Duration::from_millis(1), Duration::from_millis(10), |_| {
            count.set(count.get() + 1);
            Err::<(), _>("always fails")
        });
        assert_eq!(result, Err("always fails"));
        assert_eq!(count.get(), 3); // 1 initial + 2 retries
    }

    #[test]
    fn zero_retries_means_single_attempt() {
        let count = Cell::new(0u32);
        let result = retry_with_backoff(0, Duration::from_millis(100), Duration::from_secs(1), |_| {
            count.set(count.get() + 1);
            Err::<(), _>("fail")
        });
        assert_eq!(result, Err("fail"));
        assert_eq!(count.get(), 1);
    }

    #[test]
    fn respects_max_delay_cap() {
        let start = Instant::now();
        let _ = retry_with_backoff(3, Duration::from_secs(100), Duration::from_millis(5), |_| {
            Err::<(), _>("fail")
        });
        let elapsed = start.elapsed();
        // 3 sleeps capped at 5ms each = ~15ms, definitely under 1s
        assert!(elapsed < Duration::from_secs(1));
    }
}
```

Edge cases handled:

- `max_retries = 0` — runs the operation exactly once, no sleep.
- `max_retries = u32::MAX` — `saturating_add` prevents overflow when computing total attempts.
- Large exponents — `attempt.min(63)` prevents bit-shift overflow in `2^n`.
- Huge `initial_delay` — `saturating_mul` clamps to `Duration::MAX` instead of panicking, then `min(max_delay)` brings it back down.
- No sleep after the final failed attempt — avoids a pointless wait when we're about to return the error.
- Attempt index passed to the closure — lets callers log or adjust behavior per attempt.

If you need async, swap `thread::sleep` for `tokio::time::sleep(...).await` and make the closure `async`. The backoff logic stays identical.

Here's a practical test suite for a nested JSON parser. I'll assume we're testing a `parseNestedJson` function that takes a string and returns a parsed object, with proper error handling.

```typescript
import { describe, it, expect } from 'vitest';
import { parseNestedJson } from './parseNestedJson';

describe('parseNestedJson', () => {
  // --- Happy path ---

  it('parses a flat object', () => {
    const input = '{"name": "Alice", "age": 30}';
    expect(parseNestedJson(input)).toEqual({ name: 'Alice', age: 30 });
  });

  it('parses deeply nested objects', () => {
    const input = '{"a": {"b": {"c": {"d": "deep"}}}}';
    const result = parseNestedJson(input);
    expect(result.a.b.c.d).toBe('deep');
  });

  it('parses nested arrays', () => {
    const input = '{"matrix": [[1, 2], [3, 4]]}';
    expect(parseNestedJson(input)).toEqual({ matrix: [[1, 2], [3, 4]] });
  });

  it('parses mixed nested structures', () => {
    const input = '{"users": [{"name": "Bob", "tags": ["admin", "active"]}]}';
    const result = parseNestedJson(input);
    expect(result.users[0].name).toBe('Bob');
    expect(result.users[0].tags).toContain('admin');
  });

  it('handles all JSON primitive types', () => {
    const input = '{"str": "hello", "num": 42, "float": 3.14, "bool": true, "nil": null}';
    const result = parseNestedJson(input);
    expect(result.str).toBe('hello');
    expect(result.num).toBe(42);
    expect(result.float).toBeCloseTo(3.14);
    expect(result.bool).toBe(true);
    expect(result.nil).toBeNull();
  });

  it('handles empty objects and arrays', () => {
    const input = '{"empty_obj": {}, "empty_arr": []}';
    expect(parseNestedJson(input)).toEqual({ empty_obj: {}, empty_arr: [] });
  });

  // --- Edge cases ---

  it('handles unicode and escaped characters', () => {
    const input = '{"msg": "hello\\nworld", "emoji": "\\u2603"}';
    const result = parseNestedJson(input);
    expect(result.msg).toBe('hello\nworld');
    expect(result.emoji).toBe('☃');
  });

  it('handles keys with special characters', () => {
    const input = '{"foo.bar": 1, "baz qux": 2, "": 3}';
    const result = parseNestedJson(input);
    expect(result['foo.bar']).toBe(1);
    expect(result['baz qux']).toBe(2);
    expect(result['']).toBe(3);
  });

  it('handles large numeric values', () => {
    const input = '{"big": 9007199254740991}';
    expect(parseNestedJson(input).big).toBe(Number.MAX_SAFE_INTEGER);
  });

  // --- Depth limits (if your parser enforces them) ---

  it('rejects nesting beyond max depth', () => {
    const depth = 128;
    const input = '{' + '"a":'.repeat(depth) + '1' + '}'.repeat(depth);
    expect(() => parseNestedJson(input, { maxDepth: 64 })).toThrow(/depth/i);
  });

  // --- Error handling ---

  it('throws on invalid JSON', () => {
    expect(() => parseNestedJson('{not json}')).toThrow();
  });

  it('throws on trailing commas', () => {
    expect(() => parseNestedJson('{"a": 1,}')).toThrow();
  });

  it('throws on single quotes', () => {
    expect(() => parseNestedJson("{'a': 1}")).toThrow();
  });

  it('throws on empty string input', () => {
    expect(() => parseNestedJson('')).toThrow();
  });

  it('throws on non-string input', () => {
    // @ts-expect-error testing runtime guard
    expect(() => parseNestedJson(undefined)).toThrow();
    // @ts-expect-error testing runtime guard
    expect(() => parseNestedJson(123)).toThrow();
  });

  it('throws on unclosed brackets', () => {
    expect(() => parseNestedJson('{"a": {"b": 1}')).toThrow();
  });
});
```

Key decisions in this test suite:

- Tests are grouped by concern: happy path, edge cases, depth limits, error handling.
- Each test checks one specific behavior — easy to diagnose failures.
- The depth limit test assumes an optional `maxDepth` config. If your parser doesn't have one, drop it or add it (you should — unbounded recursion is a DoS vector).
- Error tests verify the parser rejects malformed input rather than silently returning garbage.

Adapt the import path and function signature to match your actual implementation. If you're writing the parser from scratch (not wrapping `JSON.parse`), you'll also want tests for streaming/partial input and performance benchmarks on large payloads.

# Adapter Pattern

The Adapter pattern lets you make incompatible interfaces work together. It wraps an object with an incompatible interface into an adapter that the client code expects.

**When to use:** You have existing code (or a third-party library) with one interface, but your system expects a different one. You don't want to (or can't) modify the original code.

## Practical Example

Say you have a system that processes payments. Your code expects a unified `PaymentProcessor` interface, but you need to integrate two different third-party payment SDKs with completely different APIs.

```python
from dataclasses import dataclass


# --- Your system's expected interface ---

class PaymentProcessor:
    """Interface your system works with."""

    def pay(self, amount: float, currency: str) -> dict:
        raise NotImplementedError


# --- Third-party SDKs you can't modify ---

class StripeSDK:
    """Stripe-like SDK with its own API shape."""

    def create_charge(self, amount_cents: int, cur: str, idempotency_key: str) -> dict:
        # Imagine this hits a real API
        return {"id": "ch_abc123", "status": "succeeded", "amount": amount_cents}


class PayPalSDK:
    """PayPal-like SDK with a completely different API."""

    def send_payment(self, value: str, currency_code: str) -> dict:
        # Imagine this hits a real API
        return {"payment_id": "PAY-xyz", "state": "approved"}


# --- Adapters ---

class StripeAdapter(PaymentProcessor):
    def __init__(self, sdk: StripeSDK):
        self._sdk = sdk

    def pay(self, amount: float, currency: str) -> dict:
        amount_cents = int(amount * 100)
        result = self._sdk.create_charge(amount_cents, currency, idempotency_key="key123")
        return {"success": result["status"] == "succeeded", "transaction_id": result["id"]}


class PayPalAdapter(PaymentProcessor):
    def __init__(self, sdk: PayPalSDK):
        self._sdk = sdk

    def pay(self, amount: float, currency: str) -> dict:
        result = self._sdk.send_payment(value=f"{amount:.2f}", currency_code=currency)
        return {"success": result["state"] == "approved", "transaction_id": result["payment_id"]}


# --- Client code doesn't care which provider is behind the adapter ---

def checkout(processor: PaymentProcessor, amount: float, currency: str):
    result = processor.pay(amount, currency)
    if result["success"]:
        print(f"Payment {result['transaction_id']} completed.")
    else:
        print("Payment failed.")


# Usage
stripe_processor = StripeAdapter(StripeSDK())
paypal_processor = PayPalAdapter(PayPalSDK())

checkout(stripe_processor, 29.99, "USD")
checkout(paypal_processor, 29.99, "USD")
```

## Why this works well

| Without Adapter | With Adapter |
|---|---|
| Client code has `if/elif` branches for each SDK | Client code calls one uniform `.pay()` method |
| Adding a new provider means touching client logic | Adding a new provider = one new adapter class |
| Hard to test (coupled to SDK details) | Easy to mock `PaymentProcessor` in tests |

## Key points

- The adapter holds a reference to the adaptee (the incompatible object) and translates calls.
- The client depends only on the target interface, never on the concrete SDK.
- It's the same idea as a physical power adapter — you don't rewire the device, you put a converter in between.

```typescript
import { EventEmitter } from "events";

interface PoolOptions {
  minSize: number;
  maxSize: number;
  acquireTimeoutMs: number;
  idleTimeoutMs: number;
  maxLifetimeMs: number;
  validateOnAcquire: boolean;
}

interface PooledConnection<T> {
  resource: T;
  createdAt: number;
  lastUsedAt: number;
  id: number;
}

interface PendingRequest<T> {
  resolve: (conn: T) => void;
  reject: (err: Error) => void;
  timer: ReturnType<typeof setTimeout>;
}

type ConnectionFactory<T> = {
  create: () => Promise<T>;
  destroy: (resource: T) => Promise<void>;
  validate: (resource: T) => Promise<boolean>;
};

class ConnectionPool<T> extends EventEmitter {
  private options: PoolOptions;
  private factory: ConnectionFactory<T>;
  private idle: PooledConnection<T>[] = [];
  private active: Set<PooledConnection<T>> = new Set();
  private pendingRequests: PendingRequest<T>[] = [];
  private connectionId = 0;
  private closed = false;
  private idleCheckInterval: ReturnType<typeof setInterval> | null = null;

  constructor(factory: ConnectionFactory<T>, options: Partial<PoolOptions> = {}) {
    super();
    this.factory = factory;
    this.options = {
      minSize: options.minSize ?? 2,
      maxSize: options.maxSize ?? 10,
      acquireTimeoutMs: options.acquireTimeoutMs ?? 5000,
      idleTimeoutMs: options.idleTimeoutMs ?? 30000,
      maxLifetimeMs: options.maxLifetimeMs ?? 300000,
      validateOnAcquire: options.validateOnAcquire ?? true,
    };

    if (this.options.minSize < 0) throw new Error("minSize must be >= 0");
    if (this.options.maxSize < 1) throw new Error("maxSize must be >= 1");
    if (this.options.minSize > this.options.maxSize) {
      throw new Error("minSize cannot exceed maxSize");
    }

    this.startIdleCheck();
  }

  get size(): number {
    return this.idle.length + this.active.size;
  }

  get availableCount(): number {
    return this.idle.length;
  }

  get pendingCount(): number {
    return this.pendingRequests.length;
  }

  async initialize(): Promise<void> {
    const promises: Promise<void>[] = [];
    for (let i = 0; i < this.options.minSize; i++) {
      promises.push(this.addConnection());
    }
    await Promise.all(promises);
  }

  async acquire(): Promise<T> {
    if (this.closed) {
      throw new Error("Pool is closed");
    }

    // Try to get an idle connection
    while (this.idle.length > 0) {
      const conn = this.idle.pop()!;

      if (this.isExpired(conn)) {
        await this.destroyConnection(conn);
        continue;
      }

      if (this.options.validateOnAcquire) {
        try {
          const valid = await this.factory.validate(conn.resource);
          if (!valid) {
            await this.destroyConnection(conn);
            continue;
          }
        } catch {
          await this.destroyConnection(conn);
          continue;
        }
      }

      conn.lastUsedAt = Date.now();
      this.active.add(conn);
      this.emit("acquire", conn.id);
      return conn.resource;
    }

    // No idle connections — create one if under max
    if (this.size < this.options.maxSize) {
      const conn = await this.createConnection();
      conn.lastUsedAt = Date.now();
      this.active.add(conn);
      this.emit("acquire", conn.id);
      return conn.resource;
    }

    // At capacity — wait in queue
    return new Promise<T>((resolve, reject) => {
      const timer = setTimeout(() => {
        const idx = this.pendingRequests.findIndex((r) => r.timer === timer);
        if (idx !== -1) {
          this.pendingRequests.splice(idx, 1);
        }
        reject(new Error(`Acquire timeout after ${this.options.acquireTimeoutMs}ms`));
      }, this.options.acquireTimeoutMs);

      this.pendingRequests.push({ resolve, reject, timer });
    });
  }

  async release(resource: T): Promise<void> {
    if (this.closed) {
      // Pool closed while resource was checked out — just destroy
      try {
        await this.factory.destroy(resource);
      } catch {
        // swallow
      }
      return;
    }

    const conn = this.findActive(resource);
    if (!conn) {
      // Double release or unknown resource — ignore silently
      return;
    }

    this.active.delete(conn);
    conn.lastUsedAt = Date.now();

    if (this.isExpired(conn)) {
      await this.destroyConnection(conn);
      this.ensureMinSize();
      return;
    }

    // Serve a pending request first
    if (this.pendingRequests.length > 0) {
      const pending = this.pendingRequests.shift()!;
      clearTimeout(pending.timer);
      conn.lastUsedAt = Date.now();
      this.active.add(conn);
      this.emit("acquire", conn.id);
      pending.resolve(conn.resource);
      return;
    }

    // Return to idle pool
    this.idle.push(conn);
    this.emit("release", conn.id);
  }

  async destroy(resource: T): Promise<void> {
    const conn = this.findActive(resource);
    if (conn) {
      this.active.delete(conn);
      await this.destroyConnection(conn);
      this.ensureMinSize();
    }
  }

  async drain(): Promise<void> {
    this.closed = true;

    if (this.idleCheckInterval) {
      clearInterval(this.idleCheckInterval);
      this.idleCheckInterval = null;
    }

    // Reject all pending requests
    for (const pending of this.pendingRequests) {
      clearTimeout(pending.timer);
      pending.reject(new Error("Pool is draining"));
    }
    this.pendingRequests = [];

    // Destroy all idle connections
    const destroyPromises = this.idle.map((conn) => this.destroyConnection(conn));
    this.idle = [];
    await Promise.all(destroyPromises);

    // Wait for active connections to be released (with a hard timeout)
    if (this.active.size > 0) {
      await Promise.race([
        new Promise<void>((resolve) => {
          const check = setInterval(() => {
            if (this.active.size === 0) {
              clearInterval(check);
              resolve();
            }
          }, 100);
        }),
        new Promise<void>((resolve) => setTimeout(resolve, 10000)),
      ]);

      // Force-destroy any remaining
      const remaining = [...this.active];
      this.active.clear();
      await Promise.all(remaining.map((conn) => this.destroyConnection(conn)));
    }

    this.emit("drain");
  }

  private async createConnection(): Promise<PooledConnection<T>> {
    const resource = await this.factory.create();
    const conn: PooledConnection<T> = {
      resource,
      createdAt: Date.now(),
      lastUsedAt: Date.now(),
      id: ++this.connectionId,
    };
    this.emit("create", conn.id);
    return conn;
  }

  private async destroyConnection(conn: PooledConnection<T>): Promise<void> {
    try {
      await this.factory.destroy(conn.resource);
    } catch (err) {
      this.emit("error", err);
    }
    this.emit("destroy", conn.id);
  }

  private async addConnection(): Promise<void> {
    try {
      const conn = await this.createConnection();
      this.idle.push(conn);
    } catch (err) {
      this.emit("error", err);
    }
  }

  private findActive(resource: T): PooledConnection<T> | undefined {
    for (const conn of this.active) {
      if (conn.resource === resource) return conn;
    }
    return undefined;
  }

  private isExpired(conn: PooledConnection<T>): boolean {
    const now = Date.now();
    return now - conn.createdAt > this.options.maxLifetimeMs;
  }

  private startIdleCheck(): void {
    this.idleCheckInterval = setInterval(async () => {
      if (this.closed) return;

      const now = Date.now();
      const toRemove: PooledConnection<T>[] = [];

      this.idle = this.idle.filter((conn) => {
        const idle = now - conn.lastUsedAt > this.options.idleTimeoutMs;
        const expired = this.isExpired(conn);
        const surplus = this.size > this.options.minSize;

        if ((idle || expired) && surplus) {
          toRemove.push(conn);
          return false;
        }
        return true;
      });

      for (const conn of toRemove) {
        await this.destroyConnection(conn);
      }

      this.ensureMinSize();
    }, Math.min(this.options.idleTimeoutMs / 2, 5000));
  }

  private ensureMinSize(): void {
    if (this.closed) return;
    const deficit = this.options.minSize - this.size;
    for (let i = 0; i < deficit; i++) {
      this.addConnection();
    }
  }
}

export { ConnectionPool, ConnectionFactory, PoolOptions };
```

Key design decisions and edge cases handled:

- **Acquire timeout** — callers don't hang forever when pool is exhausted. Queued requests get rejected after the configured timeout.
- **Connection validation** — stale/broken connections are detected on acquire and silently replaced.
- **Max lifetime eviction** — prevents connections from living forever (important for DB failovers, DNS changes, etc.).
- **Idle timeout with minimum guarantee** — idle connections get reaped, but the pool never shrinks below `minSize`.
- **Double release** — silently ignored instead of corrupting state.
- **Release after drain** — resource gets destroyed instead of returned to a dead pool.
- **Graceful drain** — rejects pending waiters, destroys idle connections, waits (with hard timeout) for active ones, then force-destroys stragglers.
- **Factory errors** — creation/destruction failures are caught and emitted rather than crashing the pool.
- **FIFO queue fairness** — pending requests are served in order when connections become available.

Usage would look like:

```typescript
const pool = new ConnectionPool({
  create: () => connectToDb(),
  destroy: (conn) => conn.close(),
  validate: (conn) => conn.ping(),
}, { maxSize: 20, acquireTimeoutMs: 3000 });

await pool.initialize();

const conn = await pool.acquire();
try {
  await conn.query("SELECT 1");
} finally {
  await pool.release(conn);
}
```

